<h1>Hosting Management</h1><?php if(current_user_role()==='Admin'): ?><a class='btn' href='<?= url('hosts/create') ?>'>Add Host</a><?php endif; ?><table><tr><th>ID</th><th>Company</th><th>Contact</th><th>Email</th><th>Verified</th><th>Actions</th></tr><?php foreach($hosts as $h): ?><tr><td><?= e($h['host_id']) ?></td><td><?= e($h['company_name']) ?></td><td><?= e($h['contact_person']) ?></td><td><?= e($h['email']) ?></td><td><?= $h['is_verified']?'Yes':'No' ?></td><td><a href='<?= url('hosts/edit?id='.$h['host_id']) ?>'>Edit</a> | <a onclick="return confirm('Delete host?')" href='<?= url('hosts/delete?id='.$h['host_id']) ?>'>Delete</a></td></tr><?php endforeach; ?></table>
